function buildCommand() {
  const __args = [['passwordstrength'], 'Network Tools', 'Check the strength of a password (local check, not sent anywhere)', async ({ sock, from, msg, args }) => {
  const pw = args.join(' ');
  if (!pw) return sock.sendMessage(from, { text: 'Usage: .passwordstrength <password>' }, { quoted: msg });
  let score = 0;
  if (pw.length >= 8) score++;
  if (pw.length >= 12) score++;
  if (/[A-Z]/.test(pw)) score++;
  if (/[0-9]/.test(pw)) score++;
  if (/[^A-Za-z0-9]/.test(pw)) score++;
  const labels = ['Very weak', 'Weak', 'Fair', 'Good', 'Strong', 'Very strong'];
  await sock.sendMessage(from, { text: `🔐 Strength: ${labels[score]} (${score}/5)` }, { quoted: msg });
}];
  const [commandsArr, section, description, handler, opts = {}] = __args;
  return { commands: commandsArr, section, description, handler, ownerOnly: !!opts.ownerOnly };
}

module.exports = buildCommand();
